<?php
/**
 * Basic theme setup: what the theme supports, where its menus go,
 * and which WP extras we drop from the page.
 */

defined( 'ABSPATH' ) || exit;

add_action(
	'after_setup_theme',
	static function () {
		// <title> is generated by WP (and by an SEO plugin, if one gets installed).
		add_theme_support( 'title-tag' );
		add_theme_support( 'html5', array( 'script', 'style' ) );

		// Menu locations. The menus themselves are built in Appearance → Menus.
		register_nav_menus(
			array(
				'primary'        => 'Header',
				'footer_company' => 'Footer: first column',
				'footer_links'   => 'Footer: second column',
			)
		);
	}
);

// Remove what the site doesn't need from <head>.
remove_action( 'wp_head', 'print_emoji_detection_script', 7 );
remove_action( 'wp_print_styles', 'print_emoji_styles' );
remove_action( 'wp_head', 'wp_generator' );
remove_action( 'wp_head', 'rsd_link' );
remove_action( 'wp_head', 'wp_shortlink_wp_head' );

add_action(
	'wp_enqueue_scripts',
	static function () {
		// Block theme styles. Among other things they underline every link,
		// and since they sit outside CSS layers they would override Tailwind.
		wp_dequeue_style( 'global-styles' );
		wp_dequeue_style( 'classic-theme-styles' );
	},
	100
);

// If no Site Icon is set in Settings → General, use the favicons from assets/favicon/.
add_action(
	'wp_head',
	static function () {
		if ( has_site_icon() ) {
			return;
		}

		$icons = array(
			array( 'icon', 'assets/favicon/favicon.ico', 'sizes="48x48"' ),
			array( 'icon', 'assets/favicon/favicon-32.png', 'type="image/png" sizes="32x32"' ),
			array( 'icon', 'assets/favicon/favicon-192.png', 'type="image/png" sizes="192x192"' ),
			array( 'apple-touch-icon', 'assets/favicon/apple-touch-icon.png', 'sizes="180x180"' ),
		);

		foreach ( $icons as [ $rel, $file, $attrs ] ) {
			printf( '<link rel="%s" href="%s" %s />' . "\n", esc_attr( $rel ), esc_url( get_theme_file_uri( $file ) ), $attrs );
		}
	}
);

// Direct /favicon.ico requests: WordPress redirects them to its own logo when no Site Icon is set.
add_action(
	'do_faviconico',
	static function () {
		if ( ! has_site_icon() ) {
			wp_redirect( get_theme_file_uri( 'assets/favicon/favicon.ico' ) );
			exit;
		}
	}
);

/*
 * Pages are built from the page builder's blocks (SCF fields, see inc/blocks.php), so they
 * open in the classic editor: Gutenberg content isn't rendered on pages, and the classic
 * screen shows the builder right away without scrolling.
 */
add_filter(
	'use_block_editor_for_post_type',
	static fn( $use, $post_type ) => 'page' === $post_type ? false : $use,
	10,
	2
);

/*
 * SVG uploads to the Media Library — only for users who may already insert any HTML
 * (administrators). An SVG can contain scripts, so nobody else gets this.
 */
add_filter(
	'upload_mimes',
	static function ( $mimes ) {
		if ( current_user_can( 'unfiltered_html' ) ) {
			$mimes['svg'] = 'image/svg+xml';
		}

		return $mimes;
	}
);

add_filter(
	'wp_check_filetype_and_ext',
	static function ( $data, $file, $filename, $mimes ) {
		if ( ! $data['type'] && isset( $mimes['svg'] ) && 'svg' === strtolower( pathinfo( $filename, PATHINFO_EXTENSION ) ) ) {
			$data['ext']  = 'svg';
			$data['type'] = 'image/svg+xml';
		}

		return $data;
	},
	10,
	4
);
